import React, { useState, useEffect } from 'react';
import './Perfil_user.css';
import NavMenu from '../../navMenu/NavMenu';
import { FiUser, FiMail, FiPhone, FiLock, FiImage } from 'react-icons/fi';
import { getUserData, setUserData } from '../LocalStorangUser/LocalstorangUser';
import { LogalstorangUSER, Buscar_Orders_Users } from '../../../Redux/Actions/Usuario/Action-user';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import Loading from '../../loading/Loading';

const PerfilUser = () => {
  const [loading, setLoading] = useState(true);
  const user = useSelector((state) => state.USER);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    nombre: '',
    apellido: '',
    celular: '',
    email: '',
    pass: '',
  });
  const [imagePreview, setImagePreview] = useState(null);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  useEffect(() => {
    const timer = setTimeout(() => {
      setLoading(false);
    }, 3000);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const storedUser = getUserData();
    if (!user || user.state === "false") {
      if (!storedUser || storedUser.state === "false") {
        navigate('/');
      } else {
        dispatch(Buscar_Orders_Users(storedUser.id));
        dispatch(LogalstorangUSER(storedUser));
      }
    } else {
      setUserData(user);
    }
  }, [navigate, user, dispatch]);

  useEffect(() => {
    if (user && user.state !== "false") {
      setFormData({
        nombre: user.name,
        apellido: user.apell,
        celular: user.celular,
        email: user.email,
       
      });
      setImagePreview(user.url);
    }
  }, [user]);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleEditClick = () => {
    setIsEditing(true);
  };

  const handleSaveClick = () => {
    // Lógica para guardar los datos
    setIsEditing(false);
  };

  const handleCancelClick = () => {
    // Revertir los cambios si se cancela la edición
    setFormData({
      nombre: user.nombre,
      apellido: user.apellido,
      celular: user.celular,
      email: user.email,
      pass: user.pass,
    });
    setIsEditing(false);
  };

  return (
    <>
      {loading && <Loading />}
      <NavMenu className="nav-menu" />
      <div className='body-user-perfil-centar'>
        <div className='form-perfil'>
          <h2>PERFIL USUARIO</h2>
          <div className="Login-container-input">
            <div className="input-group">
              <FiUser className="input-icon user-icon" />
              <input
                type='text'
                name='nombre'
                placeholder='Nombre'
                className="perfil-user-input"
                value={formData.nombre}
                onChange={handleChange}
                disabled={!isEditing}
              />
            </div>
            <div className="input-container perfil-user-apellido">
              <FiUser className="input-icon user-icon" />
              <input
                type='text'
                name='apellido'
                placeholder='Apellido'
                className="perfil-user-input"
                value={formData.apellido}
                onChange={handleChange}
                disabled={!isEditing}
              />
            </div>
            <div className="input-container perfil-user-celular">
              <FiPhone className="input-icon phone-icon" />
              <input
                type='tel'
                name='celular'
                placeholder='Celular'
                className="perfil-user-input"
                value={formData.celular}
                onChange={handleChange}
                disabled={!isEditing}
              />
            </div>
            <div className="input-container perfil-user-email">
              <FiMail className="input-icon mail-icon" />
              <input
                type='email'
                name='email'
                placeholder='Correo'
                className="perfil-user-input"
                value={formData.email}
                onChange={handleChange}
                disabled={!isEditing}
              />
            </div>
            <div className="input-container perfil-user-pass">
              <FiLock className="input-icon lock-icon" />
              <input
                type='password'
                name='pass'
                placeholder='Contraseña'
                className="perfil-user-input"
                value={formData.pass}
                onChange={handleChange}
                disabled={!isEditing}
              />
            </div>
            <div className="input-group">
              <FiImage className="input-icon image-icon" />
              <input
                type="file"
                name="image"
                accept="image/*"
                className="perfil-user-input"
                onChange={handleImageChange}
                disabled={!isEditing}
              />
            </div>
          </div>
          {!isEditing ? (
            <div className="btn-editar" onClick={handleEditClick}>Editar</div>
          ) : (
            <>
              <div className="btn-editar" onClick={handleSaveClick}>Guardar</div>
              <div className="btn-editar" onClick={handleCancelClick}>Cancelar</div>
            </>
          )}
        </div>
        <div className="image-preview">
          <img src={imagePreview} alt="Preview" />
        </div>
      </div>
    </>
  );
};

export default PerfilUser;
